import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64

// Tiled fp32 GEMM: C(M,N) = A(M,K) * B(K,N), all row-major.
// Block computes a 16x16 tile of C, looping over K in 32-wide chunks
// staged through shared memory. Grid = (ceil(N/16), ceil(M/16), 1),
// block = (16, 16, 1).
.visible .entry matmul_tiled(
    .param .u64 param_A,
    .param .u64 param_B,
    .param .u64 param_C,
    .param .u32 param_M,
    .param .u32 param_N,
    .param .u32 param_K
)
{
    .reg .pred %p<8>;
    .reg .b32 %r<40>;
    .reg .b64 %rd<12>;
    .reg .f32 %f<8>;

    .shared .align 4 .b8 smemA[2048];   // 16 x 32 floats
    .shared .align 4 .b8 smemB[2048];   // 32 x 16 floats

    ld.param.u64 %rd1, [param_A];
    ld.param.u64 %rd2, [param_B];
    ld.param.u64 %rd3, [param_C];
    ld.param.u32 %r30, [param_M];
    ld.param.u32 %r31, [param_N];
    ld.param.u32 %r32, [param_K];

    mov.u32 %r1, %tid.x;                // tx (0..15)
    mov.u32 %r2, %tid.y;                // ty (0..15)
    mov.u32 %r3, %ctaid.x;              // bx
    mov.u32 %r4, %ctaid.y;              // by

    shl.b32 %r5, %r2, 4;
    add.s32 %r5, %r5, %r1;              // tid = ty*16 + tx

    shl.b32 %r6, %r4, 4;                // rowBase = by*16
    shl.b32 %r7, %r3, 4;                // colBase = bx*16

    mov.u32 %r13, smemA;                // shared base of A tile
    mov.u32 %r17, smemB;                // shared base of B tile

    mov.f32 %f1, 0f00000000;            // accumulator
    mov.u32 %r8, 0;                     // k0

$K_LOOP:
    // ---- load A tile element 0 (idx = tid) ----
    shr.b32 %r9, %r5, 5;                // row = idx / 32
    and.b32 %r10, %r5, 31;              // col = idx % 32
    add.s32 %r11, %r6, %r9;             // globalRow
    add.s32 %r12, %r8, %r10;            // globalK = k0 + col
    setp.lt.u32 %p1, %r11, %r30;
    setp.lt.u32 %p2, %r12, %r32;
    and.pred %p1, %p1, %p2;
    mul.wide.u32 %rd4, %r11, %r32;
    cvt.u64.u32 %rd5, %r12;
    add.u64 %rd4, %rd4, %rd5;
    shl.b64 %rd4, %rd4, 2;
    add.u64 %rd4, %rd1, %rd4;
    mov.f32 %f2, 0f00000000;
    @%p1 ld.global.f32 %f2, [%rd4];
    shl.b32 %r14, %r5, 2;
    add.s32 %r15, %r13, %r14;
    st.shared.f32 [%r15], %f2;

    // ---- load A tile element 1 (idx = tid + 256) ----
    add.s32 %r16, %r5, 256;
    shr.b32 %r9, %r16, 5;
    and.b32 %r10, %r16, 31;
    add.s32 %r11, %r6, %r9;
    add.s32 %r12, %r8, %r10;
    setp.lt.u32 %p1, %r11, %r30;
    setp.lt.u32 %p2, %r12, %r32;
    and.pred %p1, %p1, %p2;
    mul.wide.u32 %rd4, %r11, %r32;
    cvt.u64.u32 %rd5, %r12;
    add.u64 %rd4, %rd4, %rd5;
    shl.b64 %rd4, %rd4, 2;
    add.u64 %rd4, %rd1, %rd4;
    mov.f32 %f2, 0f00000000;
    @%p1 ld.global.f32 %f2, [%rd4];
    shl.b32 %r14, %r16, 2;
    add.s32 %r15, %r13, %r14;
    st.shared.f32 [%r15], %f2;

    // ---- load B tile element 0 (idx = tid) ----
    shr.b32 %r9, %r5, 4;                // rowB = idx / 16
    and.b32 %r10, %r5, 15;              // colB = idx % 16
    add.s32 %r11, %r8, %r9;             // globalKRow = k0 + rowB
    add.s32 %r12, %r7, %r10;            // globalCol = colBase + colB
    setp.lt.u32 %p1, %r11, %r32;
    setp.lt.u32 %p2, %r12, %r31;
    and.pred %p1, %p1, %p2;
    mul.wide.u32 %rd4, %r11, %r31;
    cvt.u64.u32 %rd5, %r12;
    add.u64 %rd4, %rd4, %rd5;
    shl.b64 %rd4, %rd4, 2;
    add.u64 %rd4, %rd2, %rd4;
    mov.f32 %f2, 0f00000000;
    @%p1 ld.global.f32 %f2, [%rd4];
    shl.b32 %r14, %r5, 2;
    add.s32 %r15, %r17, %r14;
    st.shared.f32 [%r15], %f2;

    // ---- load B tile element 1 (idx = tid + 256) ----
    add.s32 %r16, %r5, 256;
    shr.b32 %r9, %r16, 4;
    and.b32 %r10, %r16, 15;
    add.s32 %r11, %r8, %r9;
    add.s32 %r12, %r7, %r10;
    setp.lt.u32 %p1, %r11, %r32;
    setp.lt.u32 %p2, %r12, %r31;
    and.pred %p1, %p1, %p2;
    mul.wide.u32 %rd4, %r11, %r31;
    cvt.u64.u32 %rd5, %r12;
    add.u64 %rd4, %rd4, %rd5;
    shl.b64 %rd4, %rd4, 2;
    add.u64 %rd4, %rd2, %rd4;
    mov.f32 %f2, 0f00000000;
    @%p1 ld.global.f32 %f2, [%rd4];
    shl.b32 %r14, %r16, 2;
    add.s32 %r15, %r17, %r14;
    st.shared.f32 [%r15], %f2;

    bar.sync 0;

    // ---- accumulate over the 32-wide K chunk ----
    mov.u32 %r20, 0;                    // kk
$INNER:
    shl.b32 %r21, %r2, 5;               // ty*32
    add.s32 %r21, %r21, %r20;           // + kk
    shl.b32 %r21, %r21, 2;
    add.s32 %r21, %r13, %r21;
    ld.shared.f32 %f3, [%r21];

    shl.b32 %r22, %r20, 4;              // kk*16
    add.s32 %r22, %r22, %r1;            // + tx
    shl.b32 %r22, %r22, 2;
    add.s32 %r22, %r17, %r22;
    ld.shared.f32 %f4, [%r22];

    fma.rn.f32 %f1, %f3, %f4, %f1;

    add.s32 %r20, %r20, 1;
    setp.lt.u32 %p3, %r20, 32;
    @%p3 bra $INNER;

    bar.sync 0;

    add.s32 %r8, %r8, 32;
    setp.lt.u32 %p4, %r8, %r32;
    @%p4 bra $K_LOOP;

    // ---- write C tile with bounds check ----
    add.s32 %r24, %r6, %r2;             // globalRow = rowBase + ty
    add.s32 %r25, %r7, %r1;             // globalCol = colBase + tx
    setp.lt.u32 %p5, %r24, %r30;
    setp.lt.u32 %p6, %r25, %r31;
    and.pred %p5, %p5, %p6;
    mul.wide.u32 %rd8, %r24, %r31;
    cvt.u64.u32 %rd9, %r25;
    add.u64 %rd8, %rd8, %rd9;
    shl.b64 %rd8, %rd8, 2;
    add.u64 %rd8, %rd3, %rd8;
    @%p5 st.global.f32 [%rd8], %f1;

    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("matmul_tiled")

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()

